SELECT t.*, req.nickname AS requester_name, prov.nickname AS provider_name
FROM tasks t
LEFT JOIN user_profiles req ON req.user_id = t.requester_id
LEFT JOIN user_profiles prov ON prov.user_id = t.provider_id


    AND t.status NOT IN ('DRAFT', 'PENDING_REVIEW', 'REJECTED')


