LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM tasks t


    AND t.status NOT IN ('DRAFT', 'PENDING_REVIEW', 'REJECTED')


    AND (t.title LIKE CONCAT('%', #{keyword}, '%') OR t.description LIKE CONCAT('%', #{keyword}, '%'))


    AND t.category = #{category}


    AND t.campus = #{campus}


    AND t.status = #{status}


    AND t.status NOT IN ('DISPUTED', 'CANCELLED')


    AND t.reward_type = #{rewardType}


    AND t.requires_proof = #{requiresProof}


    AND t.deadline > NOW()

SELECT * FROM tasks t
WHERE t.status = #{status}
  AND (
    (#{status} = 'OPEN' AND t.deadline <= #{referenceTime})
    OR (#{status} = 'PENDING_CONFIRMATION' AND t.updated_at <= #{referenceTime})
  )
  AND NOT EXISTS (
    SELECT 1 FROM task_histories h
    WHERE h.task_id = t.id
      AND h.note = #{reminderNote}
      AND h.created_at >= t.updated_at
  )
ORDER BY t.updated_at ASC, t.id ASC
LIMIT #{limit}

SELECT * FROM tasks t
WHERE t.status = #{status}
  AND EXISTS (
    SELECT 1 FROM task_histories h
    WHERE h.task_id = t.id
      AND h.note = #{reminderNote}
      AND h.created_at >= t.updated_at
      AND h.created_at <= #{reminderCreatedBefore}
  )
ORDER BY t.updated_at ASC, t.id ASC
LIMIT #{limit}

SELECT * FROM tasks
WHERE status = #{status}
  AND deadline > NOW()
ORDER BY created_at DESC
LIMIT #{size}

SELECT campus
FROM (
  SELECT requester_id AS user_id, campus FROM tasks WHERE campus IS NOT NULL
  UNION ALL
  SELECT provider_id AS user_id, campus FROM tasks WHERE provider_id IS NOT NULL AND campus IS NOT NULL
) combined
WHERE user_id = #{userId}
GROUP BY campus
ORDER BY COUNT(*) DESC
LIMIT #{limit}
